import { Request, Response, NextFunction } from 'express';
import Joi from 'joi';
import { AppError } from '../types';

type ValidationSource = 'body' | 'query' | 'params';

/**
 * Validation middleware factory
 * @param schema - Joi validation schema
 * @param source - Where to validate from (body, query, params)
 */
export const validate = (
  schema: Joi.Schema,
  source: ValidationSource = 'body'
) => {
  return (req: Request, _res: Response, next: NextFunction) => {
    const { error, value } = schema.validate(req[source], {
      abortEarly: false,
      stripUnknown: true,
    });

    if (error) {
      const errorMessages = error.details.map((detail) => detail.message).join(', ');
      throw new AppError({
        status: 400,
        code: 'VALIDATION_ERROR',
        message: errorMessages,
      });
    }

    // Replace req[source] with validated and sanitized value
    req[source] = value;
    next();
  };
};

import { Request, Response, NextFunction } from 'express';
import { CustomError } from '@/modules/common/types';
import logger from '@/services/logger';
import { isDuplicateKeyError } from '@/modules/common/utils/mongoErrors';

export const errorHandler = (
  err: CustomError,
  _req: Request,
  res: Response,
  _next: NextFunction
) => {
  // TODO: here add logger.error
  logger.error(err.message, {});

  if (isDuplicateKeyError(err)) {
    return res.status(409).json({
      error: 409,
      message: 'This record already exists. Please refresh and try again.',
      code: 'DUPLICATE_RESOURCE',
    });
  }

  // if no status or message in error use default 500 code and message
  const statusCode = err.status ?? 500;
  const message = err.message || 'Something went wrong.';

  // returns error status code and message
  return res.status(statusCode).json({
    error: statusCode,
    message: message,
    code: err?.code,
  });
};

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { CONFIG } from '@/config/config';
import { AppError } from '@/modules/common/types';
import PharmacyModel from '@/modules/pharmacies/model';

export interface AuthRequest extends Request {
  user?: {
    _id: string;
    phone?: string;
    email?: string;
    corporateId?: string;
    specialistId?: string;
    pharmacyId?: string;
    userType: string;
  };
}

const decodeAuthToken = (authHeader?: string): AuthRequest['user'] | null => {
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return null;
  }

  const token = authHeader.substring(7);
  const decoded = jwt.verify(token, CONFIG.JWT_SECRET_KEY) as AuthRequest['user'];
  return decoded;
};

export const authenticate = (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): void => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      throw new AppError({
        status: 401,
        code: 'UNAUTHORIZED',
        message: 'Authorization token is required',
      });
    }

    try {
      req.user = decodeAuthToken(authHeader) || undefined;
      next();
    } catch (error: any) {
      if (error.name === 'TokenExpiredError') {
        throw new AppError({
          status: 401,
          code: 'TOKEN_EXPIRED',
          message: 'Token has expired',
        });
      } else if (error.name === 'JsonWebTokenError') {
        throw new AppError({
          status: 401,
          code: 'INVALID_TOKEN',
          message: 'Invalid token',
        });
      }
      throw error;
    }
  } catch (error) {
    next(error);
  }
};

const assertOperationalPharmacy = async (req: AuthRequest): Promise<void> => {
  const pharmacyId = req.user?.pharmacyId || req.user?._id;
  if (!pharmacyId) {
    throw new AppError({
      status: 403,
      code: 'PHARMACY_PROFILE_REQUIRED',
      message: 'Pharmacy account must be linked to a pharmacy profile',
    });
  }

  const pharmacy = await PharmacyModel.findById(pharmacyId)
    .select('_id isActive isVerified archivedAt')
    .lean();

  if (!pharmacy || pharmacy.archivedAt || pharmacy.isActive === false) {
    throw new AppError({
      status: 403,
      code: 'PHARMACY_INACTIVE',
      message: 'This pharmacy account is inactive',
    });
  }

  if (!pharmacy.isVerified) {
    throw new AppError({
      status: 403,
      code: 'PHARMACY_NOT_VERIFIED',
      message: 'Pharmacy verification is required for this operation',
    });
  }

  req.user!.pharmacyId = String(pharmacy._id);
};

/** Pharmacy business operations use this; onboarding/profile routes use requirePharmacy. */
export const requireOperationalPharmacy = async (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): Promise<void> => {
  try {
    if (!req.user) {
      throw new AppError({ status: 401, code: 'UNAUTHORIZED', message: 'Authentication is required' });
    }
    if (req.user.userType !== 'pharmacy') {
      throw new AppError({ status: 403, code: 'FORBIDDEN', message: 'Pharmacy access is required' });
    }
    await assertOperationalPharmacy(req);
    next();
  } catch (error) {
    next(error);
  }

private async settleExternalBookingPayment(params: {
  userId: string;
  savedBookingId: string;
  kind: ExternalBookingKind;
  grossAmount: number;
  corporateId?: string;
  couponCode?: string;
  useWalletBalance?: boolean;
  orderNotes: Record<string, unknown>;
}): Promise<ExternalBookingPaymentInitResponse> {
  const savedBooking = await this.externalBookingRepository.findById(
    params.savedBookingId
  );

  if (!savedBooking) {
    throw new AppError({
      status: 404,
      code: 'EXTERNAL_BOOKING_NOT_FOUND',
      message: 'External booking not found',
    });
  }

  const couponResult = await this.validateExternalBookingCoupon({
    booking: savedBooking,
    actor: {
      _id: params.userId,
      corporateId: params.corporateId,
      userType: 'user',
    },
    kind: params.kind,
    grossAmount: params.grossAmount,
    couponCode: params.couponCode,
  });

  return this.finalizeExternalPaymentSettlement({
    userId: params.userId,
    bookingId: params.savedBookingId,
    grossAmount: params.grossAmount,
    discountAmount: couponResult.discountAmount,
    couponCode: couponResult.couponCode,
    walletAlreadyApplied: 0,
    attemptUseWalletBalance: params.useWalletBalance,
    orderNotes: params.orderNotes,
  });
}

private async validateExternalBookingCoupon(params: {
  booking: IExternalBooking;
  actor: ExternalBookingActor;
  kind: ExternalBookingKind;
  grossAmount: number;
  couponCode?: string;
}): Promise<{ discountAmount: number; couponCode?: string }> {
  if (!params.couponCode || params.grossAmount <= 0) {
    return { discountAmount: 0 };
  }

  const bookingType =
    params.kind === 'doctor' ? 'external_specialist' : 'external_diagnostics';
  const targetId = params.booking.externalProviderId;
  const bookingMeta =
    params.booking.meta &&
    typeof params.booking.meta === 'object' &&
    !Array.isArray(params.booking.meta)
      ? (params.booking.meta as Record<string, unknown>)
      : {};
  const packageIds = Array.isArray(bookingMeta.packageIds)
    ? bookingMeta.packageIds
        .map((item) => String(item).trim())
        .filter(Boolean)
    : undefined;
  const testIds = Array.isArray(bookingMeta.testIds)
    ? bookingMeta.testIds
        .map((item) => String(item).trim())
        .filter(Boolean)
    : undefined;

  const couponValidation = await this.couponService.validateCoupon({
    code: params.couponCode,
    userId: params.booking.userId,
    bookingType,
    bookingId: targetId,
    packageIds,
    testIds,
    dependentId: params.booking.dependentId,
    corporateId: params.actor.corporateId,
    purchaseAmount: params.grossAmount,
  });

  if (!couponValidation.isValid || !couponValidation.coupon) {
    throw new AppError({
      status: 400,
      code: 'INVALID_COUPON',
      message: couponValidation.message || 'Coupon is not valid',
    });
  }

  return {
    discountAmount: couponValidation.discountAmount || 0,
    couponCode: couponValidation.coupon.code,
  };
}

